def gen(rng):
    def build(n, mode, cap, valmax):
        vals = rng.sample(range(1, valmax + 1), n)
        L, R, D = [-1] * n, [-1] * n, [0] * n
        if mode == 'full':
            for c in range(1, n):
                p = (c - 1) // 2
                if c % 2 == 1:
                    L[p] = c
                else:
                    R[p] = c
                D[c] = D[p] + 1
            return vals, L, R, n
        free = [(0, 0), (0, 1)]
        cnt = 1
        while cnt < n and free:
            if mode == 'deep' and rng.random() < 0.95:
                k = len(free) - 1
            else:
                k = rng.randrange(len(free))
            free[k], free[-1] = free[-1], free[k]
            p, side = free.pop()
            c = cnt
            cnt += 1
            D[c] = D[p] + 1
            if side == 0:
                L[p] = c
            else:
                R[p] = c
            if D[c] + 1 < cap:
                free.append((c, 0))
                free.append((c, 1))
        return vals, L, R, cnt

    def ser(vals, L, R):
        out = [str(vals[0])]
        q, h = [0], 0
        while h < len(q):
            u = q[h]
            h += 1
            for c in (L[u], R[u]):
                if c < 0:
                    out.append('null')
                else:
                    out.append(str(vals[c]))
                    q.append(c)
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def make(n, mode='random', cap=5000, valmax=10**9):
        vals, L, R, cnt = build(n, mode, cap, valmax)
        target = vals[rng.randrange(cnt)]
        return ser(vals, L, R) + '\n' + str(target)

    tests = ['5\n5', '7 3 9\n3', '7 3 9\n7', '1 2 3 4 5 6 7\n5', '1 2 3 null 4 null 5\n4', '1 2 3 4 5 6 7\n4', '1 2 null 3 null 4\n4', '1 2 3 4 null null 5\n5']
    for _ in range(30):
        n = rng.randint(1, 24)
        tests.append(make(n, rng.choice(['random', 'deep', 'full']), 5000, 100))
    tests.append(make(2000, 'random', 5000, 10**6))
    tests.append(make(100000, 'random'))
    tests.append(make(100000, 'full'))
    tests.append(make(100000, 'deep', 5000))
    tests.append(make(100000, 'deep', 3000))
    tests.append(make(60000, 'deep', 5000))
    return tests
